import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { basename, join } from "node:path";
import { Worker } from "node:worker_threads";
import { bittern } from "./birds/bittern.mjs";
import { coot } from "./birds/coot.cjs";
const here = import.meta.dirname;
const require = createRequire(import.meta.url);
const last = text => text.trim().split("\n").at(-1);
export const sing = () => [bittern, coot].join(" and ");
export async function songs() {
  const bitterns = join(here, "birds", "bittern.mjs");
  const coots = require.resolve("./birds/coot.cjs");
  const worker = new Worker(new URL("./birds/teal.mjs", import.meta.url));
  const teal = await new Promise((resolve, reject) => {
    worker.once("message", resolve);
    worker.once("error", reject);
  });
  await worker.terminate();
  return [
    ["bittern", last(readFileSync(bitterns, "utf8"))],
    ["coot", last(await readFile(coots, "utf8"))],
    ["teal", last(await Bun.file(`${here}/birds/teal.mjs`).text())],
    ["worker", teal],
    // What is read as text is still the code that it was.
    ["imported", (await import("./birds/bittern.mjs")).bittern],
    ["by its path", (await import(bitterns)).bittern],
    ["required", require("./birds/coot.cjs").coot],
    ["required by its path", require(coots).coot],
    ["is there", existsSync(bitterns) && statSync(coots).isFile()],
    ["listed", readdirSync(join(here, "birds")).map(name => basename(name)).sort().join()],
  ];
}
